script:
(function () {
  'use strict';
  // Human life value: the present value of the earnings a household would lose, net of the
  // earner's own living costs, from now until retirement.
  // Year k (k = 1 .. years to retirement), received at the end of the year:
  //   gross pay_k = income x (1 + g)^(k-1); benefits_k = benefits x (1 + g)^(k-1)
  //   family share_k = (gross pay_k x (1 - tax rate) + benefits_k) x (1 - personal consumption share)
  //   human life value = sum of family share_k / (1 + d)^k
  // Closed form (growing annuity): PV = C1 / (d - g) x [1 - ((1 + g) / (1 + d))^n],
  // or n x C1 / (1 + d) when d = g.
  // Verified (Node, scratch tests): $80,000, 20% tax, 25% consumption, 3% growth, 5% discount,
  // 25 years: C1 = $48,000; PV = 48,000 / 0.02 x (1 - (1.03/1.05)^25) = $916,083.78, matching the
  // year-by-year sum; with g = d = 4% and 10 years, C1 = $10,000 gives 10 x 10,000 / 1.04 =
  // $96,153.85; with 0% growth and 0% discount the value equals the plain total.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  // --- calc start
  function lifeValue(p) {
    var n = p.retireAge - p.age, pv = 0, total = 0, rows = [];
    for (var k = 1; k <= n; k++) {
      var grow = Math.pow(1 + p.growth, k - 1);
      var gross = p.income * grow, ben = p.benefits * grow;
      var afterTax = gross * (1 - p.tax) + ben;
      var family = afterTax * (1 - p.consumption);
      var disc = family / Math.pow(1 + p.discount, k);
      pv += disc;
      total += family;
      rows.push({ year: k, age: p.age + k - 1, gross: gross, afterTax: afterTax, family: family, pv: disc });
    }
    return { pv: pv, total: total, years: n, first: rows.length ? rows[0].family : 0, rows: rows };
  }

  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function setText(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var p = { age: Math.round(num('hlAge')), retireAge: Math.round(num('hlRetireAge')), income: num('hlIncome'),
              growth: num('hlGrowth'), tax: num('hlTax'), consumption: num('hlConsumption'), discount: num('hlDiscount'),
              benefits: num('hlBenefits'), cover: num('hlCover') };
    var error = document.getElementById('hlError');
    var msg = '';
    if (Object.keys(p).some(function (k) { return isNaN(p[k]); })) msg = 'Fill in every field.';
    else if (p.age < 16 || p.age > 90 || p.retireAge <= p.age || p.retireAge > 90) msg = 'Enter an age from 16 to 90 and a retirement age after it (up to 90).';
    else if (p.income < 0 || p.benefits < 0 || p.cover < 0 || p.income + p.benefits <= 0) msg = 'Enter an income above $0 (and amounts of $0 or more).';
    else if (p.growth < -10 || p.growth > 20 || p.discount < 0 || p.discount > 20) msg = 'Enter income growth from -10% to 20% and a discount rate from 0% to 20%.';
    else if (p.tax < 0 || p.tax > 100 || p.consumption < 0 || p.consumption > 100) msg = 'Enter the tax rate and personal spending share from 0% to 100%.';
    error.hidden = msg === '';
    if (msg) { error.textContent = msg; return; }
    ['growth', 'tax', 'consumption', 'discount'].forEach(function (k) { p[k] /= 100; });
    var r = lifeValue(p);
    setText('hlValue', money.format(r.pv));
    setText('hlTotal', money.format(r.total));
    setText('hlFirst', money.format(r.first));
    setText('hlYears', r.years + (r.years === 1 ? ' year' : ' years'));
    setText('hlMultiple', p.income > 0 ? (r.pv / p.income).toFixed(1) + '× your current income' : '–');
    var gap = r.pv - p.cover;
    setText('hlGap', gap > 0 ? money.format(gap) : 'None — existing cover meets this value');
    document.getElementById('hlSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + row.age + '</td><td>' + money.format(row.gross) + '</td><td>' +
        money.format(row.afterTax) + '</td><td>' + money.format(row.family) + '</td><td>' + money.format(row.pv) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('hlForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
